load-full.dagger.json:
{
  "$schema": "https://example.com/schema.json",
  "name": "legacy-name",
  "engineVersion": "v0.20.3",
  "sdk": {
    "source": "go",
    "pin": "sha256:sdk",
    "config": {
      "alpha": {
        "enabled": true
      },
      "zeta": [
        "last",
        2
      ]
    },
    "debug": true,
    "experimental": {
      "alpha": true,
      "zeta": false
    }
  },
  "blueprint": {
    "name": "blueprint",
    "source": "github.com/example/blueprint",
    "pin": "sha256:blueprint",
    "customizations": [
      {
        "function": [
          "build",
          "run"
        ],
        "argument": "source",
        "default": ".",
        "defaultPath": "src",
        "defaultAddress": "alpine",
        "ignore": [
          "tmp/**"
        ]
      }
    ],
    "ignoreChecks": [
      "lint"
    ],
    "ignoreGenerators": [
      "docs"
    ],
    "ignoreServices": [
      "db"
    ],
    "portMappings": {
      "db": [
        "5432:5432"
      ],
      "web": [
        "8080:80"
      ]
    }
  },
  "toolchains": [
    {
      "name": "tools",
      "source": "github.com/example/tools"
    }
  ],
  "include": [
    "src/**",
    "!vendor/**",
    "keep/**"
  ],
  "dependencies": [
    {
      "name": "",
      "source": "string-dependency"
    },
    {
      "name": "object-dependency",
      "source": "github.com/example/object",
      "pin": "sha256:object",
      "customizations": [
        {
          "argument": "mode",
          "default": "fast"
        }
      ],
      "ignoreChecks": [
        "slow"
      ],
      "ignoreGenerators": [
        "client"
      ],
      "ignoreServices": [
        "cache"
      ],
      "portMappings": {
        "api": [
          "9090:90"
        ]
      }
    }
  ],
  "source": "./src",
  "codegen": {
    "automaticGitignore": false
  },
  "clients": [
    {
      "generator": "go",
      "directory": "./client"
    }
  ],
  "disableDefaultFunctionCaching": false
}

